    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef _list_build(vals):\n    head = cur = ListNode()\n    for v in vals:\n        cur.next = ListNode(v)\n        cur = cur.next\n    return head.next\n\ndef _list_show(head):\n    out = []\n    while head:\n        out.append(head.val)\n        head = head.next\n    return out\n\ndef _list_array_build(arr):\n    return [_list_build(x) for x in arr]\n\ndef _list_array_show(arr):\n    return [_list_show(x) for x in arr]\n\nclass Solution:\n    # \u7ffb\u8f6c\u4e00\u4e2a\u5b50\u94fe\u8868\uff0c\u5e76\u4e14\u8fd4\u56de\u65b0\u7684\u5934\u4e0e\u5c3e\n    def reverse(self, head: ListNode, tail: ListNode):\n        prev = tail.next\n        p = head\n        while prev != tail:\n            nex = p.next\n            p.next = prev\n            prev = p\n            p = nex\n        return tail, head\n\n    def reverseKGroup(self, head: ListNode, k: int) -> ListNode:\n        hair = ListNode(0)\n        hair.next = head\n        pre = hair\n\n        while head:\n            tail = pre\n            # \u67e5\u770b\u5269\u4f59\u90e8\u5206\u957f\u5ea6\u662f\u5426\u5927\u4e8e\u7b49\u4e8e k\n            for i in range(k):\n                tail = tail.next\n                if not tail:\n                    return hair.next\n            nex = tail.next\n            head, tail = self.reverse(head, tail)\n            # \u628a\u5b50\u94fe\u8868\u91cd\u65b0\u63a5\u56de\u539f\u94fe\u8868\n            pre.next = head\n            tail.next = nex\n            pre = tail\n            head = tail.next\n        \n        return hair.next\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n    _args[0] = _list_build(_args[0])\n    _ret = _sol.reverseKGroup(_args[0], _args[1])\n    _out = json.dumps(_list_show(_ret), separators=(',', ':'))\n    sys.stdout.write(_out)\n\nmain()\n",
