    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef _list_build(vals):\n    head = cur = ListNode()\n    for v in vals:\n        cur.next = ListNode(v)\n        cur = cur.next\n    return head.next\n\ndef _list_show(head):\n    out = []\n    while head:\n        out.append(head.val)\n        head = head.next\n    return out\n\ndef _list_array_build(arr):\n    return [_list_build(x) for x in arr]\n\ndef _list_array_show(arr):\n    return [_list_show(x) for x in arr]\n\n# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, x):\n#         self.val = x\n#         self.next = None\n\nclass Solution:\n    def mergeKLists(self, lists: List[ListNode]) -> ListNode:\n        import heapq\n        dummy = ListNode(0)\n        p = dummy\n        head = []\n        for i in range(len(lists)):\n            if lists[i] :\n                heapq.heappush(head, (lists[i].val, i))\n                lists[i] = lists[i].next\n        while head:\n            val, idx = heapq.heappop(head)\n            p.next = ListNode(val)\n            p = p.next\n            if lists[idx]:\n                heapq.heappush(head, (lists[idx].val, idx))\n                lists[idx] = lists[idx].next\n        return dummy.next\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n    _args[0] = _list_array_build(_args[0])\n    _ret = _sol.mergeKLists(_args[0])\n    _out = json.dumps(_list_show(_ret), separators=(',', ':'))\n    sys.stdout.write(_out)\n\nmain()\n",
