    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Node:\n    def __init__(self, value, left):\n        self.value = value\n        self.left = left\n        self.prev = None\n        self.next = None\n\nclass Solution:\n    def minimumPairRemoval(self, nums: List[int]) -> int:\n        class PQItem:\n            def __init__(self, first, second, cost):\n                self.first = first\n                self.second = second\n                self.cost = cost\n\n            def __lt__(self, other):\n                if self.cost == other.cost:\n                    return self.first.left < other.first.left\n                return self.cost < other.cost\n\n        pq = []\n        head = Node(nums[0], 0)\n        current = head\n        merged = [False] * len(nums)\n        decrease_count = 0\n        count = 0\n\n        for i in range(1, len(nums)):\n            new_node = Node(nums[i], i)\n            current.next = new_node\n            new_node.prev = current\n            heapq.heappush(pq, PQItem(current, new_node, current.value + new_node.value))\n\n            if nums[i - 1] > nums[i]:\n                decrease_count += 1\n\n            current = new_node\n\n        while decrease_count > 0:\n            item = heapq.heappop(pq)\n            first, second, cost = item.first, item.second, item.cost\n\n            if merged[first.left] or merged[second.left] or first.value + second.value != cost:\n                continue\n            count += 1\n\n            if first.value > second.value:\n                decrease_count -= 1\n\n            prev_node = first.prev\n            next_node = second.next\n            first.next = next_node\n            if next_node:\n                next_node.prev = first\n\n            if prev_node:\n                if prev_node.value > first.value and prev_node.value <= cost:\n                    decrease_count -= 1\n                elif prev_node.value <= first.value and prev_node.value > cost:\n                    decrease_count += 1\n\n                heapq.heappush(pq, PQItem(prev_node, first, prev_node.value + cost))\n\n            if next_node:\n                if second.value > next_node.value and cost <= next_node.value:\n                    decrease_count -= 1\n                elif second.value <= next_node.value and cost > next_node.value:\n                    decrease_count += 1\n                heapq.heappush(pq, PQItem(first, next_node, cost + next_node.value))\n\n            first.value = cost\n            merged[second.left] = True\n\n        return count\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minimumPairRemoval(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
